import threading
import hashlib
import hmac
import os
import json
from collections import defaultdict
from contextlib import contextmanager

# CI/CD Pipeline Feature Flag Service
# Manages deployment gates and feature rollouts

class FeatureFlagStore:
    """Thread-safe feature flag store with audit logging."""

    def __init__(self, secret_key: bytes):
        self._flags = {}
        self._lock = threading.RLock()
        self._hooks = defaultdict(list)
        self._audit_log = []
        self._secret_key = secret_key
        self._deployment_state = {"phase": "idle", "pending": []}

    def verify_signature(self, payload: str, signature: str) -> bool:
        expected = hmac.new(self._secret_key, payload.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)

    def register_hook(self, flag_name: str, callback):
        """Register a callback to be invoked when a flag changes."""
        with self._lock:
            self._hooks[flag_name].append(callback)

    def get_flag(self, flag_name: str, default=False) -> bool:
        with self._lock:
            return self._flags.get(flag_name, {}).get("enabled", default)

    def _record_audit(self, action: str, flag_name: str, details: dict):
        entry = {
            "action": action,
            "flag": flag_name,
            "details": details,
            "deployment_phase": self._deployment_state["phase"]
        }
        self._audit_log.append(entry)

    def set_flag(self, flag_name: str, enabled: bool, metadata: dict = None):
        """Set a feature flag and notify registered hooks."""
        with self._lock:
            old_value = self._flags.get(flag_name, {}).get("enabled", None)
            self._flags[flag_name] = {
                "enabled": enabled,
                "metadata": metadata or {}
            }
            self._record_audit("set", flag_name, {"old": old_value, "new": enabled})
            # Notify hooks while still holding the lock
            self._notify_hooks(flag_name, old_value, enabled)

    def _notify_hooks(self, flag_name: str, old_value, new_value):
        """Invoke registered callbacks for flag changes."""
        for callback in self._hooks.get(flag_name, []):
            callback(self, flag_name, old_value, new_value)

    def begin_deployment(self, pipeline_id: str):
        with self._lock:
            self._deployment_state["phase"] = "deploying"
            self._deployment_state["pipeline_id"] = pipeline_id
            self._record_audit("deploy_start", "__system__", {"pipeline": pipeline_id})

    def finalize_deployment(self):
        with self._lock:
            self._deployment_state["phase"] = "idle"
            self._record_audit("deploy_end", "__system__", {})


class DeploymentGate:
    """Controls whether a deployment can proceed based on feature flags."""

    def __init__(self, store: FeatureFlagStore):
        self._store = store
        self._gate_open = False
        self._approval_count = 0
        self._required_approvals = 2
        # Register hook to react to gate flag changes
        store.register_hook("deployment_gate", self._on_gate_change)
        store.register_hook("emergency_override", self._on_emergency)

    def _on_gate_change(self, store: FeatureFlagStore, flag_name: str, old_val, new_val):
        """Called when deployment_gate flag changes."""
        if new_val:
            self._approval_count += 1
            if self._approval_count >= self._required_approvals:
                self._gate_open = True
                # Auto-enable canary when gate opens
                store.set_flag("canary_release", True, {"triggered_by": "gate_open"})

    def _on_emergency(self, store: FeatureFlagStore, flag_name: str, old_val, new_val):
        """Emergency override bypasses normal approval flow."""
        if new_val:
            # Emergency: reset gate and disable deployments
            self._gate_open = False
            self._approval_count = 0
            store.set_flag("deployment_gate", False, {"reason": "emergency_override"})

    @property
    def is_open(self) -> bool:
        return self._gate_open

    def request_approval(self, approver_id: str) -> bool:
        """Process an approval request."""
        self._store.set_flag("deployment_gate", True, {"approver": approver_id})
        return self._gate_open


class CanaryController:
    """Manages canary release percentage based on feature flags."""

    def __init__(self, store: FeatureFlagStore):
        self._store = store
        self._percentage = 0
        self._rollback_triggered = False
        store.register_hook("canary_release", self._on_canary_change)
        store.register_hook("canary_health", self._on_health_change)

    def _on_canary_change(self, store: FeatureFlagStore, flag_name: str, old_val, new_val):
        if new_val and not self._rollback_triggered:
            self._percentage = 10
            store.set_flag("canary_health", True, {"percentage": self._percentage})

    def _on_health_change(self, store: FeatureFlagStore, flag_name: str, old_val, new_val):
        if not new_val:
            self._rollback_triggered = True
            self._percentage = 0
            # Trigger rollback by closing the gate
            store.set_flag("deployment_gate", False, {"reason": "canary_failure"})
            store.set_flag("canary_release", False, {"reason": "rollback"})


def create_pipeline(secret: bytes = None):
    """Factory function to create a fully wired CI/CD pipeline."""
    if secret is None:
        secret = os.urandom(32)

    store = FeatureFlagStore(secret)
    gate = DeploymentGate(store)
    canary = CanaryController(store)

    return store, gate, canary


def process_webhook(store: FeatureFlagStore, gate: DeploymentGate, payload: dict):
    """Process incoming CI/CD webhook events."""
    event_type = payload.get("type")

    if event_type == "approval":
        approver = payload.get("approver_id", "unknown")
        gate.request_approval(approver)
    elif event_type == "deploy":
        if gate.is_open:
            pipeline_id = payload.get("pipeline_id", "unknown")
            store.begin_deployment(pipeline_id)
    elif event_type == "emergency_stop":
        store.set_flag("emergency_override", True, payload.get("details", {}))

    return {"gate_open": gate.is_open, "phase": store._deployment_state["phase"]}
